 1→import i18n from '@/plugins/i18n/index.js'
 2→
 3→export default {
 4→
 5→    required: v => v !== null && v !== undefined && v !== '' || i18n.global.tc('required_field'),
 6→
 7→    // Email
 8→    email: value => {
 9→        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/; 
10→        return emailRegex.test(value) || 'Por favor, ingresa un correo electrónico válido.';
11→    },
12→    
13→    uniqueEmail: (value, emails) => {
14→        const count = emails.filter(email => email === value).length;
15→        return count <= 1 || 'Este correo ya está en uso.';
16→    },
17→    
18→    uniqueDocument: (value, documents) => {
19→        const count = documents.filter(doc => doc === value).length;
20→        return count <= 1 || 'Este número de documento ya está en uso.';
21→    },
22→
23→    min: len => v => (v || '').length >= len || `Invalid character length, required ${len}`,
24→
25→    password: v => !!(v || '').match(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*(_|[^\w])).+$/) ||
26→      'La contraseña debe tener al menos una mayúscula, una minúscula, un número y un caracter especial (como @, #, $, etc.)',
27→
28→    matchingPasswords: match => v => match == v || 'Las contraseñas no coinciden',
29→
30→    fileSize: size => v => !v || v.size < size || `File size should be less than ${size / 100000} MB!`,
31→
32→    validateMinValue: v => v >= 1 || 'Debe ser al menos 1',
33→
34→    validateDecimals: v => /^\d+(\.\d{1,2})?$/.test(v) || 'Máximo dos decimales permitidos',
35→}
